                    output reg[2:0]  u_b_h_w_EX,
                    output reg       MIO_EX
                );

    // TODO: implement — ID/EX pipeline register
    // On reset: clear rd_EX, RegWrite_EX, WR_EX, IR_EX, PCurrent_EX, rs1_EX, rs2_EX, MIO_EX to 0.
    // When EN is asserted:
    //   - If flush: insert a pipeline bubble — set IR_EX to NOP (32'h00000000), clear rd_EX,
    //     RegWrite_EX, WR_EX, MIO_EX to 0, but still pass PCurrent_ID to PCurrent_EX.
    //   - Else: latch all input signals to their corresponding output registers
    //     (PCurrent, IR, rs1/rs2 data and addresses, immediate, rd, ALU controls,
    //      DatatoReg, RegWrite, WR, u_b_h_w, MIO).

endmodule

