module FU_mul(
    input clk, EN,
    input[31:0] A, B,
    output[31:0] res,
    output finish
);

    reg[6:0] state;
    assign finish = state[0] == 1'b1;
    initial begin
        state = 0;
    end

    // TODO: implement — multiplication functional unit
    // On EN & ~|state: latch inputs (A, B) and set state to 7'b100_0000.
    // State shifts right each cycle (64-cycle latency).
    // finish when state[0] == 1.
    // Instantiate multiplier IP and use lower 32 bits of result.
    assign res = 32'b0;

