module     Regs(input clk,
				input rst,
				input [4:0] R_addr_A, 
				input [4:0] R_addr_B, 
				input [4:0] Wt_addr, 
				input [31:0]Wt_data, 
				input L_S, 
				output [31:0] rdata_A, 
				output [31:0] rdata_B,
				input [4:0] Debug_addr,         // debug address
				output[31:0] Debug_regs        // debug data
			  );

reg [31:0] register [1:31]; 				// r1 - r31
integer i;
wire write_hit_A = L_S && (Wt_addr != 0) && (Wt_addr == R_addr_A);
wire write_hit_B = L_S && (Wt_addr != 0) && (Wt_addr == R_addr_B);
wire write_hit_D = L_S && (Wt_addr != 0) && (Wt_addr == Debug_addr);

	assign rdata_A = (R_addr_A == 0) ? 32'b0 :
	                 write_hit_A ? Wt_data : register[R_addr_A];
	assign rdata_B = (R_addr_B == 0) ? 32'b0 :
	                 write_hit_B ? Wt_data : register[R_addr_B];

	always @(negedge clk or posedge rst)
      begin
		if (rst==1) 	 begin
		    for (i=1; i<32; i=i+1)
		        register[i] <= 0;
		end
        else if (L_S && (Wt_addr != 0)) begin
            register[Wt_addr] <= Wt_data;
        end
	end

    assign Debug_regs = (Debug_addr == 0) ? 32'b0 :
                        write_hit_D ? Wt_data : register[Debug_addr];

endmodule

