module FU_div(
    input clk, EN,
    input[31:0] A, B,
    output[31:0] res,
    output finish
);

    reg state;
    reg[31:0] a_reg, b_reg;
    wire[31:0] quotient;

    assign finish = state;
    assign quotient = (b_reg == 32'b0) ? 32'hFFFF_FFFF :
                      ((a_reg == 32'h8000_0000) && (b_reg == 32'hFFFF_FFFF)) ? 32'h8000_0000 :
                      $signed(a_reg) / $signed(b_reg);
    assign res = quotient;

    initial begin
        state = 1'b0;
        a_reg = 32'b0;
        b_reg = 32'b0;
    end

    always @(posedge clk) begin
        if (EN && ~state) begin
            state <= 1'b1;
            a_reg <= A;
            b_reg <= B;
        end
        else if (state) begin
            state <= 1'b0;
        end
    end

endmodule

