module FU_jump(
	input clk, EN, JALR,
	input[3:0] cmp_ctrl,
	input[31:0] rs1_data, rs2_data, imm, PC,
	output[31:0] PC_jump, PC_wb,
	output is_jump, finish
);

	reg state;
    reg jalr_reg;
    reg[3:0] cmp_ctrl_reg;
    reg[31:0] rs1_reg, rs2_reg, imm_reg, pc_reg;

    wire cmp_res;
    wire[31:0] jump_base;

	assign finish = state;
    assign jump_base = jalr_reg ? rs1_reg : pc_reg;
	assign is_jump = cmp_ctrl_reg[0] | cmp_res;

	initial begin
        state = 1'b0;
        jalr_reg = 1'b0;
        cmp_ctrl_reg = 4'b0;
        rs1_reg = 32'b0;
        rs2_reg = 32'b0;
        imm_reg = 32'b0;
        pc_reg = 32'b0;
    end

    always @(posedge clk) begin
        if (EN && ~state) begin
            state <= 1'b1;
            jalr_reg <= JALR;
            cmp_ctrl_reg <= cmp_ctrl;
            rs1_reg <= rs1_data;
            rs2_reg <= rs2_data;
            imm_reg <= imm;
            pc_reg <= PC;
        end
        else if (state) begin
            state <= 1'b0;
        end
    end

    cmp_32 cmp(
        .a(rs1_reg),
        .b(rs2_reg),
        .ctrl(cmp_ctrl_reg[3:1]),
        .c(cmp_res)
    );

    add_32 add_jump(
        .a(jump_base),
        .b(imm_reg),
        .c(PC_jump)
    );

    add_32 add_wb(
        .a(pc_reg),
        .b(32'd4),
        .c(PC_wb)
    );

endmodule

