module FU_mul(
    input clk, EN,
    input[31:0] A, B,
    output[31:0] res,
    output finish
);

    reg[6:0] state;
    reg[31:0] a_reg, b_reg;
    wire[63:0] mul_res;

    assign finish = state[0];
    assign mul_res = $signed(a_reg) * $signed(b_reg);
    assign res = mul_res[31:0];

    initial begin
        state = 7'b0;
        a_reg = 32'b0;
        b_reg = 32'b0;
    end

    always @(posedge clk) begin
        if (EN && ~|state) begin
            state <= 7'b100_0000;
            a_reg <= A;
            b_reg <= B;
        end
        else if (|state) begin
            state <= {1'b0, state[6:1]};
        end
    end

endmodule

