module FU_ALU(
    input clk, EN,
    input[3:0] ALUControl,
    input[31:0] ALUA, ALUB,
    output[31:0] res,
    output zero, overflow,
    output finish
);
    localparam ALU_ADD  = 4'b0001;
    localparam ALU_SUB  = 4'b0010;
    localparam ALU_AND  = 4'b0011;
    localparam ALU_OR   = 4'b0100;
    localparam ALU_XOR  = 4'b0101;
    localparam ALU_SLL  = 4'b0110;
    localparam ALU_SRL  = 4'b0111;
    localparam ALU_SLT  = 4'b1000;
    localparam ALU_SLTU = 4'b1001;
    localparam ALU_SRA  = 4'b1010;
    localparam ALU_Ap4  = 4'b1011;
    localparam ALU_Bout = 4'b1100;

    reg state;
    reg[3:0] ctrl_reg;
    reg[31:0] a_reg, b_reg;

    wire[4:0] shamt = b_reg[4:0];
    wire[31:0] add_res = a_reg + b_reg;
    wire[31:0] sub_res = a_reg - b_reg;

    assign finish = state;

    initial begin
        state = 1'b0;
        ctrl_reg = 4'b0;
        a_reg = 32'b0;
        b_reg = 32'b0;
    end

    always @(posedge clk) begin
        if (EN && ~state) begin
            state <= 1'b1;
            ctrl_reg <= ALUControl;
            a_reg <= ALUA;
            b_reg <= ALUB;
        end
        else if (state) begin
            state <= 1'b0;
        end
    end

    assign res = (ctrl_reg == ALU_ADD)  ? add_res :
                 (ctrl_reg == ALU_SUB)  ? sub_res :
                 (ctrl_reg == ALU_AND)  ? (a_reg & b_reg) :
                 (ctrl_reg == ALU_OR)   ? (a_reg | b_reg) :
                 (ctrl_reg == ALU_XOR)  ? (a_reg ^ b_reg) :
                 (ctrl_reg == ALU_SLL)  ? (a_reg << shamt) :
                 (ctrl_reg == ALU_SRL)  ? (a_reg >> shamt) :
                 (ctrl_reg == ALU_SLT)  ? {31'b0, $signed(a_reg) < $signed(b_reg)} :
                 (ctrl_reg == ALU_SLTU) ? {31'b0, a_reg < b_reg} :
                 (ctrl_reg == ALU_SRA)  ? ($signed(a_reg) >>> shamt) :
                 (ctrl_reg == ALU_Ap4)  ? (a_reg + 32'd4) :
                 (ctrl_reg == ALU_Bout) ? b_reg :
                 32'b0;

    assign zero = ~|res;
    assign overflow = ((ctrl_reg == ALU_ADD) &&
                       (~(a_reg[31] ^ b_reg[31]) & (add_res[31] ^ a_reg[31]))) ||
                      ((ctrl_reg == ALU_SUB) &&
                       ((a_reg[31] ^ b_reg[31]) & (sub_res[31] ^ a_reg[31])));

endmodule

