module FU_mem(
    input clk, EN, mem_w,
    input[2:0] bhw,
    input[31:0] rs1_data, rs2_data, imm,
    output[31:0] mem_data,
    output finish
);

    reg[1:0] state;
    assign finish = state[0] == 1'b1;
    initial begin
        state = 0;
    end

    reg mem_w_reg;
    reg[2:0] bhw_reg;
    reg[31:0] rs1_data_reg, rs2_data_reg, imm_reg;

    // TODO: implement — memory functional unit
    // On EN & ~|state: latch inputs (mem_w, bhw, rs1_data, rs2_data, imm) and set state to 2'b10.
    // State shifts right each cycle (2'b10 -> 2'b01 -> 2'b00).
    // finish when state[0] == 1.
    // Compute address = rs1_data_reg + imm_reg using add_32.
    // Instantiate RAM_B with computed address.
    assign mem_data = 32'b0;

endmodule

