module FU_div(
    input clk, EN,
    input[31:0] A, B,
    output[31:0] res,
    output finish
);

    wire res_valid;
    wire[63:0] divres;

    reg state;
    assign finish = res_valid & state;
    initial begin
        state = 0;
    end

    reg A_valid, B_valid;
    reg[31:0] A_reg, B_reg;

    // TODO: implement — division functional unit
    // On EN & ~state: latch inputs (A, B), set A_valid and B_valid to 1, set state to 1.
    // When res_valid: clear A_valid, B_valid, state to 0.
    // Otherwise: clear A_valid, B_valid but keep state.
    // Instantiate divider IP with AXI-style valid/data interface.
    // Result is the quotient from divres[63:32].
    assign res = 32'b0;

endmodule

`timescale 1ns / 1ps

module FU_mul(
    input clk, EN,
    input[31:0] A, B,
    output[31:0] res,
    output finish
);

    reg[6:0] state;
    assign finish = state[0] == 1'b1;
    initial begin
        state = 0;
    end

    // TODO: implement — multiplication functional unit
    // On EN & ~|state: latch inputs (A, B) and set state to 7'b100_0000.
    // State shifts right each cycle (64-cycle latency).
    // finish when state[0] == 1.
    // Instantiate multiplier IP and use lower 32 bits of result.
    assign res = 32'b0;

endmodule

