	output[31:0] PC_jump, PC_wb,
	output is_jump, finish
);

	wire cmp_res;
    reg state;
    assign finish = state == 1'b1;
	initial begin
        state = 0;
    end

	reg JALR_reg;
	reg[3:0] cmp_ctrl_reg = 0;
	reg[31:0] rs1_data_reg = 0, rs2_data_reg = 0, imm_reg = 0, PC_reg = 0;

    // TODO: implement — jump/branch functional unit
    // On EN & ~state: latch inputs (JALR, cmp_ctrl, rs1_data, rs2_data, imm, PC) and set state to 1.
    // On state==1: reset state to 0.
    // Use cmp_32 to compare rs1_data_reg and rs2_data_reg.
    // Compute PC_jump = (JALR ? rs1_data_reg : PC_reg) + imm_reg.
    // Compute PC_wb = PC_reg + 4.
    // is_jump = cmp_ctrl_reg[0] | cmp_res (unconditional or condition met).
    assign is_jump = 1'b0;
    assign PC_jump = 32'b0;
    assign PC_wb = 32'b0;

endmodule

