module RAM_B(
    input [31:0] addra,
    input clka,      // normal clock
    input[31:0] dina,
    input wea, 
    output[31:0] douta,
    output [7:0] sim_uart_char_out,
    output sim_uart_char_valid,
    input[2:0] mem_u_b_h_w
);
    localparam SIZE = 256;
    localparam ADDR_LINE = $clog2(SIZE);
    localparam SIM_UART_ADDR = 32'h10000000;

    reg[7:0] data[0:SIZE-1];
    reg [7:0] uart_char;
    reg uart_valid;

    initial	begin
        $readmemh("ram.mem", data);
    end

    always @ (negedge clka) begin
        uart_valid <= 1'b0;
        if (wea) begin
            if (addra == SIM_UART_ADDR) begin
                uart_char <= dina[7:0];
                uart_valid <= 1'b1;
            end
            else if (addra[31:ADDR_LINE] == 0) begin
                data[addra[ADDR_LINE-1:0]] <= dina[7:0];
                if (mem_u_b_h_w[0] | mem_u_b_h_w[1]) begin
                    data[addra[ADDR_LINE-1:0] + 1'b1] <= dina[15:8];
                end
                if (mem_u_b_h_w[1]) begin
                    data[addra[ADDR_LINE-1:0] + 2'd2] <= dina[23:16];
                    data[addra[ADDR_LINE-1:0] + 2'd3] <= dina[31:24];
                end
            end
        end
    end

    assign douta = (addra == SIM_UART_ADDR || addra[31:ADDR_LINE] != 0) ? 32'b0 :
                   mem_u_b_h_w[1] ? {data[addra[ADDR_LINE-1:0] + 2'd3],
                                     data[addra[ADDR_LINE-1:0] + 2'd2],
                                     data[addra[ADDR_LINE-1:0] + 1'b1],
                                     data[addra[ADDR_LINE-1:0]]} :
                   mem_u_b_h_w[0] ? {{16{~mem_u_b_h_w[2] &
                                         data[addra[ADDR_LINE-1:0] + 1'b1][7]}},
                                     data[addra[ADDR_LINE-1:0] + 1'b1],
                                     data[addra[ADDR_LINE-1:0]]} :
                   {{24{~mem_u_b_h_w[2] & data[addra[ADDR_LINE-1:0]][7]}},
                    data[addra[ADDR_LINE-1:0]]};

    assign sim_uart_char_valid = uart_valid;
    assign sim_uart_char_out = uart_char;
endmodule

