module RV32core(
        input debug_en,
        input debug_step,
        input [6:0] debug_addr,
        output [31:0] debug_data,
        output [31:0] wb_addr,
        output [31:0] wb_data,
        output reg [31:0] clk_counter,
        input clk,
        input rst,
        input interrupter
    );

    wire debug_clk;
    wire [31:0] debug_regs;
    reg [31:0] Test_signal;
    wire jump_flush;
    wire reg_if_is_en;

    assign debug_data = debug_addr[5] ? Test_signal : debug_regs;

    debug_clk clock(.clk(clk), .debug_en(debug_en), .debug_step(debug_step), .debug_clk(debug_clk));

    wire PC_EN_IF, IS_EN, FU_ALU_EN, FU_mem_EN, FU_mul_EN, FU_div_EN, FU_jump_EN;
    wire RegWrite_ctrl, ALUSrcA_ctrl, ALUSrcB_ctrl, mem_w_ctrl;
    wire [2:0] ImmSel_ctrl, bhw_ctrl, DatatoReg_ctrl;
    wire [3:0] ALUControl_ctrl;
    wire [4:0] Jump_ctrl;
    wire [4:0] rs1_addr_ctrl, rs2_addr_ctrl, rd_ctrl;
    wire [31:0] PC_ctrl, imm_ctrl;

    wire [31:0] PC_IF, next_PC_IF, PC_4_IF, inst_IF;
    wire [31:0] inst_IS, PC_IS, Imm_out_IS;
    wire [31:0] rs1_data_RO, rs2_data_RO, ALUA_RO, ALUB_RO;
    wire FU_ALU_finish, FU_mem_finish, FU_mul_finish, FU_div_finish, FU_jump_finish, is_jump_FU;
    wire [31:0] ALUout_FU, mem_data_FU, mulres_FU, divres_FU, PC_jump_FU, PC_wb_FU;
    wire [31:0] ALUout_WB, mem_data_WB, mulres_WB, divres_WB, PC_wb_WB, wt_data_WB;
    reg [31:0] issue_pc, issue_inst;
    wire [31:0] wb_pc = issue_pc;
    wire [31:0] wb_inst = issue_inst;

    assign jump_flush = FU_jump_finish & is_jump_FU;
    assign reg_if_is_en = IS_EN | jump_flush;

    // IF
    assign PC_EN_IF = reg_if_is_en;

    REG32 REG_PC(.clk(debug_clk), .rst(rst), .CE(PC_EN_IF), .D(next_PC_IF), .Q(PC_IF));

    add_32 add_IF(.a(PC_IF), .b(32'd4), .c(PC_4_IF));

    MUX2T1_32 mux_IF(.I0(PC_4_IF), .I1(PC_jump_FU), .s(jump_flush), .o(next_PC_IF));

    ROM_D inst_rom(.a(PC_IF[8:2]), .spo(inst_IF));

    // Issue
    REG_IF_IS reg_IF_IS(
        .clk(debug_clk),
        .rst(rst),
        .EN(reg_if_is_en),
        .flush(jump_flush),
        .PCOUT(PC_IF),
        .IR(inst_IF),
        .IR_IS(inst_IS),
        .PCurrent_IS(PC_IS)
    );

    ImmGen imm_gen(.ImmSel(ImmSel_ctrl), .inst_field(inst_IS), .Imm_out(Imm_out_IS));

    CtrlUnit ctrl(
        .clk(debug_clk),
        .rst(rst),
        .PC(PC_IS),
        .inst(inst_IS),
        .imm(Imm_out_IS),
        .ALU_done(FU_ALU_finish),
        .MEM_done(FU_mem_finish),
        .MUL_done(FU_mul_finish),
        .DIV_done(FU_div_finish),
        .JUMP_done(FU_jump_finish),
        .is_jump(is_jump_FU),
        .IS_en(IS_EN),
        .ImmSel(ImmSel_ctrl),
        .ALU_en(FU_ALU_EN),
        .MEM_en(FU_mem_EN),
        .MUL_en(FU_mul_EN),
        .DIV_en(FU_div_EN),
        .JUMP_en(FU_jump_EN),
        .PC_ctrl(PC_ctrl),
        .imm_ctrl(imm_ctrl),
        .rs1_ctrl(rs1_addr_ctrl),
        .rs2_ctrl(rs2_addr_ctrl),
        .JUMP_op(Jump_ctrl),
        .ALU_op(ALUControl_ctrl),
        .ALU_use_PC(ALUSrcA_ctrl),
        .ALU_use_imm(ALUSrcB_ctrl),
        .MEM_we(mem_w_ctrl),
        .MEM_bhw(bhw_ctrl),
        .MUL_op(),
        .DIV_op(),
        .write_sel(DatatoReg_ctrl),
        .reg_write(RegWrite_ctrl),
        .rd_ctrl(rd_ctrl)
    );

    // RO
    Regs register(
        .clk(debug_clk),
        .rst(rst),
        .R_addr_A(rs1_addr_ctrl),
        .rdata_A(rs1_data_RO),
        .R_addr_B(rs2_addr_ctrl),
        .rdata_B(rs2_data_RO),
        .L_S(RegWrite_ctrl),
        .Wt_addr(rd_ctrl),
        .Wt_data(wt_data_WB),
        .Debug_addr(debug_addr[4:0]),
        .Debug_regs(debug_regs)
    );

    MUX2T1_32 mux_imm_ALU_RO_A(.I0(rs1_data_RO), .I1(PC_ctrl), .s(ALUSrcA_ctrl), .o(ALUA_RO));
    MUX2T1_32 mux_imm_ALU_RO_B(.I0(rs2_data_RO), .I1(imm_ctrl), .s(ALUSrcB_ctrl), .o(ALUB_RO));

    // FU
    FU_ALU alu(.clk(debug_clk), .EN(FU_ALU_EN), .finish(FU_ALU_finish),
        .ALUControl(ALUControl_ctrl), .ALUA(ALUA_RO), .ALUB(ALUB_RO), .res(ALUout_FU),
        .zero(), .overflow());

    FU_mem mem(.clk(debug_clk), .EN(FU_mem_EN), .finish(FU_mem_finish),
        .mem_w(mem_w_ctrl), .bhw(bhw_ctrl), .rs1_data(rs1_data_RO), .rs2_data(rs2_data_RO),
        .imm(imm_ctrl), .mem_data(mem_data_FU));

    FU_mul mu(.clk(debug_clk), .EN(FU_mul_EN), .finish(FU_mul_finish),
        .A(rs1_data_RO), .B(rs2_data_RO), .res(mulres_FU));

    FU_div du(.clk(debug_clk), .EN(FU_div_EN), .finish(FU_div_finish),
        .A(rs1_data_RO), .B(rs2_data_RO), .res(divres_FU));

    FU_jump ju(.clk(debug_clk), .EN(FU_jump_EN), .finish(FU_jump_finish),
        .JALR(Jump_ctrl[4]), .cmp_ctrl(Jump_ctrl[3:0]), .rs1_data(rs1_data_RO), .rs2_data(rs2_data_RO),
        .imm(imm_ctrl), .PC(PC_ctrl), .PC_jump(PC_jump_FU), .PC_wb(PC_wb_FU), .is_jump(is_jump_FU));

    // WB
    REG32 reg_WB_ALU(.clk(debug_clk), .rst(rst), .CE(FU_ALU_finish), .D(ALUout_FU), .Q(ALUout_WB));
    REG32 reg_WB_mem(.clk(debug_clk), .rst(rst), .CE(FU_mem_finish), .D(mem_data_FU), .Q(mem_data_WB));
    REG32 reg_WB_mul(.clk(debug_clk), .rst(rst), .CE(FU_mul_finish), .D(mulres_FU), .Q(mulres_WB));
    REG32 reg_WB_div(.clk(debug_clk), .rst(rst), .CE(FU_div_finish), .D(divres_FU), .Q(divres_WB));
    REG32 reg_WB_jump(.clk(debug_clk), .rst(rst), .CE(FU_jump_finish), .D(PC_wb_FU), .Q(PC_wb_WB));

    MUX8T1_32 mux_DtR(.s(DatatoReg_ctrl), .I0(ALUout_FU), .I1(mem_data_FU), .I2(mulres_FU), .I3(divres_FU),
        .I4(PC_wb_FU), .I5(32'd0), .I6(32'd0), .I7(32'd0), .o(wt_data_WB));

    assign wb_addr = rd_ctrl;
    assign wb_data = wt_data_WB;

    always @(posedge debug_clk) begin
        if (rst) begin
            clk_counter <= 32'b0;
            issue_pc <= 32'b0;
            issue_inst <= 32'b0;
        end
        else begin
            clk_counter <= clk_counter + 32'd1;
            if (FU_ALU_EN | FU_mem_EN | FU_mul_EN | FU_div_EN | FU_jump_EN) begin
                issue_pc <= PC_IS;
                issue_inst <= inst_IS;
            end
        end
    end

    always @* begin
        case (debug_addr[4:0])
            0:  Test_signal = PC_IF;
            1:  Test_signal = inst_IF;
            2:  Test_signal = PC_IS;
            3:  Test_signal = inst_IS;
            4:  Test_signal = rs1_addr_ctrl;
            5:  Test_signal = rs1_data_RO;
            6:  Test_signal = rs2_addr_ctrl;
            7:  Test_signal = rs2_data_RO;
            8:  Test_signal = ImmSel_ctrl;
            9:  Test_signal = imm_ctrl;
            10: Test_signal = ALUout_FU;
            11: Test_signal = PC_EN_IF;
            12: Test_signal = {15'b0, FU_ALU_EN, 15'b0, FU_ALU_finish};
            13: Test_signal = ALUControl_ctrl;
            14: Test_signal = ALUA_RO;
            15: Test_signal = ALUB_RO;
            16: Test_signal = {15'b0, FU_mem_EN, 15'b0, FU_mem_finish};
            17: Test_signal = mem_w_ctrl;
            18: Test_signal = bhw_ctrl;
            19: Test_signal = mem_data_FU;
            20: Test_signal = {15'b0, FU_mul_EN, 15'b0, FU_mul_finish};
            21: Test_signal = mulres_FU;
            22: Test_signal = {15'b0, FU_div_EN, 15'b0, FU_div_finish};
            23: Test_signal = divres_FU;
            24: Test_signal = {15'b0, FU_jump_EN, 15'b0, FU_jump_finish};
            25: Test_signal = Jump_ctrl;
            26: Test_signal = PC_jump_FU;
            27: Test_signal = PC_wb_FU;
            28: Test_signal = RegWrite_ctrl;
            29: Test_signal = rd_ctrl;
            30: Test_signal = DatatoReg_ctrl;
            31: Test_signal = wt_data_WB;
            default: Test_signal = 32'hAA55_AA55;
        endcase
    end

endmodule

`timescale 1ns / 1ps
`include "CtrlDefine.vh"

module CtrlUnit(
    input clk,
    input rst,

    input [31:0] PC,
    input [31:0] inst,
    input [31:0] imm,

    input ALU_done,
    input MEM_done,
    input MUL_done,
    input DIV_done,
    input JUMP_done,
    input is_jump,

    output IS_en,
    output [2:0] ImmSel,
    output reg ALU_en,
    output reg MEM_en,
    output reg MUL_en,
    output reg DIV_en,
    output reg JUMP_en,
    output reg [31:0] PC_ctrl,
    output reg [31:0] imm_ctrl,
    output reg [4:0] rs1_ctrl,
    output reg [4:0] rs2_ctrl,
    output reg [4:0] JUMP_op,
    output reg [3:0] ALU_op,
    output reg ALU_use_PC,
    output reg ALU_use_imm,
    output reg MEM_we,
    output reg [2:0] MEM_bhw,
    output reg [2:0] MUL_op,
    output reg [1:0] DIV_op,
    output reg [2:0] write_sel,
    output reg reg_write,
    output reg [4:0] rd_ctrl
);

    localparam ST_READY = 1'b0;
    localparam ST_WAIT  = 1'b1;

    localparam ALU_ADD  = 4'b0001;
    localparam ALU_SUB  = 4'b0010;
    localparam ALU_AND  = 4'b0011;
    localparam ALU_OR   = 4'b0100;
    localparam ALU_XOR  = 4'b0101;
    localparam ALU_SLL  = 4'b0110;
    localparam ALU_SRL  = 4'b0111;
    localparam ALU_SLT  = 4'b1000;
    localparam ALU_SLTU = 4'b1001;
    localparam ALU_SRA  = 4'b1010;
    localparam ALU_BOUT = 4'b1100;

    reg state;
    reg [2:0] active_fu;
    reg [2:0] active_write_sel;
    reg active_reg_write;
    reg [4:0] active_rd;

    wire [6:0] funct7 = inst[31:25];
    wire [2:0] funct3 = inst[14:12];
    wire [6:0] opcode = inst[6:0];
    wire [4:0] rd = inst[11:7];
    wire [4:0] rs1 = inst[19:15];
    wire [4:0] rs2 = inst[24:20];

    wire Rop = opcode == 7'b0110011;
    wire Iop = opcode == 7'b0010011;
    wire Bop = opcode == 7'b1100011;
    wire Lop = opcode == 7'b0000011;
    wire Sop = opcode == 7'b0100011;

    wire funct7_0  = funct7 == 7'h00;
    wire funct7_1  = funct7 == 7'h01;
    wire funct7_32 = funct7 == 7'h20;

    wire ADD  = Rop & (funct3 == 3'h0) & funct7_0;
    wire SUB  = Rop & (funct3 == 3'h0) & funct7_32;
    wire SLL  = Rop & (funct3 == 3'h1) & funct7_0;
    wire SLT  = Rop & (funct3 == 3'h2) & funct7_0;
    wire SLTU = Rop & (funct3 == 3'h3) & funct7_0;
    wire XOR  = Rop & (funct3 == 3'h4) & funct7_0;
    wire SRL  = Rop & (funct3 == 3'h5) & funct7_0;
    wire SRA  = Rop & (funct3 == 3'h5) & funct7_32;
    wire OR   = Rop & (funct3 == 3'h6) & funct7_0;
    wire AND  = Rop & (funct3 == 3'h7) & funct7_0;

    wire MUL    = Rop & (funct3 == 3'h0) & funct7_1;
    wire MULH   = Rop & (funct3 == 3'h1) & funct7_1;
    wire MULHSU = Rop & (funct3 == 3'h2) & funct7_1;
    wire MULHU  = Rop & (funct3 == 3'h3) & funct7_1;
    wire DIV    = Rop & (funct3 == 3'h4) & funct7_1;
    wire DIVU   = Rop & (funct3 == 3'h5) & funct7_1;
    wire REM    = Rop & (funct3 == 3'h6) & funct7_1;
    wire REMU   = Rop & (funct3 == 3'h7) & funct7_1;

    wire ADDI  = Iop & (funct3 == 3'h0);
    wire SLTI  = Iop & (funct3 == 3'h2);
    wire SLTIU = Iop & (funct3 == 3'h3);
    wire XORI  = Iop & (funct3 == 3'h4);
    wire ORI   = Iop & (funct3 == 3'h6);
    wire ANDI  = Iop & (funct3 == 3'h7);
    wire SLLI  = Iop & (funct3 == 3'h1) & funct7_0;
    wire SRLI  = Iop & (funct3 == 3'h5) & funct7_0;
    wire SRAI  = Iop & (funct3 == 3'h5) & funct7_32;

    wire BEQ  = Bop & (funct3 == 3'h0);
    wire BNE  = Bop & (funct3 == 3'h1);
    wire BLT  = Bop & (funct3 == 3'h4);
    wire BGE  = Bop & (funct3 == 3'h5);
    wire BLTU = Bop & (funct3 == 3'h6);
    wire BGEU = Bop & (funct3 == 3'h7);

    wire LB  = Lop & (funct3 == 3'h0);
    wire LH  = Lop & (funct3 == 3'h1);
    wire LW  = Lop & (funct3 == 3'h2);
    wire LBU = Lop & (funct3 == 3'h4);
    wire LHU = Lop & (funct3 == 3'h5);

    wire SB = Sop & (funct3 == 3'h0);
    wire SH = Sop & (funct3 == 3'h1);
    wire SW = Sop & (funct3 == 3'h2);

    wire LUI   = opcode == 7'b0110111;
    wire AUIPC = opcode == 7'b0010111;
    wire JAL   = opcode == 7'b1101111;
    wire JALR  = (opcode == 7'b1100111) & (funct3 == 3'h0);

    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU |
                   MUL | MULH | MULHSU | MULHU | DIV | DIVU | REM | REMU;
    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
    wire L_valid = LW | LH | LB | LHU | LBU;
    wire S_valid = SW | SH | SB;

    wire use_ALU = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU |
                   I_valid | LUI | AUIPC;
    wire use_MEM = L_valid | S_valid;
    wire use_MUL = MUL | MULH | MULHSU | MULHU;
    wire use_DIV = DIV | DIVU | REM | REMU;
    wire use_JUMP = B_valid | JAL | JALR;

    wire issue_valid = use_ALU | use_MEM | use_MUL | use_DIV | use_JUMP;
    wire writes_rd = R_valid | I_valid | L_valid | LUI | AUIPC | JAL | JALR;

    wire [4:0] issue_alu_op = ({5{ADD | ADDI | AUIPC}} & `ALU_ADD)   |
                              ({5{SUB}}               & `ALU_SUB)    |
                              ({5{AND | ANDI}}        & `ALU_AND)    |
                              ({5{OR | ORI}}          & `ALU_OR)     |
                              ({5{XOR | XORI}}        & `ALU_XOR)    |
                              ({5{SLL | SLLI}}        & `ALU_SLL)    |
                              ({5{SRL | SRLI}}        & `ALU_SRL)    |
                              ({5{SLT | SLTI}}        & `ALU_SLT)    |
                              ({5{SLTU | SLTIU}}      & `ALU_SLTU)   |
                              ({5{SRA | SRAI}}        & `ALU_SRA)    |
                              ({5{LUI}}               & `ALU_LUI);

`timescale 1ns / 1ps

module FU_mem(
    input clk, EN, mem_w,
    input [2:0] bhw,
    input [31:0] rs1_data, rs2_data, imm,
    output [31:0] mem_data,
    output finish
);

    reg [1:0] state;
    reg mem_w_reg;
    reg [2:0] bhw_reg;
    reg [31:0] rs1_data_reg;
    reg [31:0] rs2_data_reg;
    reg [31:0] imm_reg;
    wire [31:0] mem_addr;

    assign finish = state[0];

    initial begin
        state = 2'b00;
        mem_w_reg = 1'b0;
        bhw_reg = 3'b0;
        rs1_data_reg = 32'b0;
        rs2_data_reg = 32'b0;
        imm_reg = 32'b0;
    end

    always @(posedge clk) begin
        if (~|state && EN) begin
            state <= 2'b10;
            mem_w_reg <= mem_w;
            bhw_reg <= bhw;
            rs1_data_reg <= rs1_data;
            rs2_data_reg <= rs2_data;
            imm_reg <= imm;
        end
        else if (|state) begin
            state <= {1'b0, state[1]};
        end
    end

    add_32 add_mem(.a(rs1_data_reg), .b(imm_reg), .c(mem_addr));

    RAM_B data_ram(
        .addra(mem_addr),
        .clka(clk),
        .dina(rs2_data_reg),
        .wea(mem_w_reg & state[1]),
        .douta(mem_data),
        .mem_u_b_h_w(bhw_reg)
    );

endmodule

`timescale 1ns / 1ps

module FU_div(
    input clk, EN,
    input [31:0] A, B,
    output [31:0] res,
    output finish
);

    reg state;
    reg [31:0] A_reg;
    reg [31:0] B_reg;

    assign finish = state;

    initial begin
        state = 1'b0;
        A_reg = 32'b0;
        B_reg = 32'b0;
    end

    always @(posedge clk) begin
        if (~state && EN) begin
            state <= 1'b1;
            A_reg <= A;
            B_reg <= B;
        end
        else begin
            state <= 1'b0;
        end
    end

    assign res = (B_reg == 32'b0) ? 32'hFFFF_FFFF :
                 ((A_reg == 32'h8000_0000) && (B_reg == 32'hFFFF_FFFF)) ? 32'h8000_0000 :
                 $signed(A_reg) / $signed(B_reg);

endmodule

    wire [4:0] issue_jump_op = ({5{BEQ}}  & `JUMP_BEQ)  |
                               ({5{BNE}}  & `JUMP_BNE)  |
                               ({5{BLT}}  & `JUMP_BLT)  |
                               ({5{BGE}}  & `JUMP_BGE)  |
                               ({5{BLTU}} & `JUMP_BLTU) |
                               ({5{BGEU}} & `JUMP_BGEU) |
                               ({5{JAL}}  & `JUMP_JAL)  |
                               ({5{JALR}} & `JUMP_JALR);

    wire [2:0] issue_fu = ({3{use_ALU}}  & `FU_ALU)  |
                          ({3{use_MEM}}  & `FU_MEM)  |
                          ({3{use_MUL}}  & `FU_MUL)  |
                          ({3{use_DIV}}  & `FU_DIV)  |
                          ({3{use_JUMP}} & `FU_JUMP);

    wire [2:0] issue_write_sel = use_MEM  ? 3'd1 :
                                 use_MUL  ? 3'd2 :
                                 use_DIV  ? 3'd3 :
                                 use_JUMP ? 3'd4 : 3'd0;

    wire [4:0] issue_src1 = {5{R_valid | I_valid | S_valid | L_valid | B_valid | JALR}} & rs1;
    wire [4:0] issue_src2 = {5{R_valid | S_valid | B_valid}} & rs2;

    wire active_done = (active_fu == `FU_ALU)  ? ALU_done  :
                       (active_fu == `FU_MEM)  ? MEM_done  :
                       (active_fu == `FU_MUL)  ? MUL_done  :
                       (active_fu == `FU_DIV)  ? DIV_done  :
                       (active_fu == `FU_JUMP) ? JUMP_done : 1'b0;

    assign IS_en = state == ST_READY;

    assign ImmSel = ({3{JALR | L_valid | I_valid}} & `Imm_type_I) |
                    ({3{B_valid}}                  & `Imm_type_B) |
                    ({3{JAL}}                      & `Imm_type_J) |
                    ({3{S_valid}}                  & `Imm_type_S) |
                    ({3{LUI | AUIPC}}              & `Imm_type_U);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= ST_READY;
            active_fu <= `FU_BLANK;
            active_write_sel <= 3'b0;
            active_reg_write <= 1'b0;
            active_rd <= 5'b0;
        end
        else if (state == ST_WAIT) begin
            if (active_done) begin
                state <= ST_READY;
                active_fu <= `FU_BLANK;
                active_write_sel <= 3'b0;
                active_reg_write <= 1'b0;
                active_rd <= 5'b0;
            end
        end
        else if (issue_valid) begin
            state <= ST_WAIT;
            active_fu <= issue_fu;
            active_write_sel <= issue_write_sel;
            active_reg_write <= writes_rd & (rd != 0);
            active_rd <= rd;
        end
    end

    always @(*) begin
        ALU_en = 1'b0;
        MEM_en = 1'b0;
        MUL_en = 1'b0;
        DIV_en = 1'b0;
        JUMP_en = 1'b0;

        PC_ctrl = 32'b0;
        imm_ctrl = 32'b0;
        rs1_ctrl = 5'b0;
        rs2_ctrl = 5'b0;

        JUMP_op = 5'b0;
        ALU_op = 4'b0;
        ALU_use_PC = 1'b0;
        ALU_use_imm = 1'b0;
        MEM_we = 1'b0;
        MEM_bhw = 3'b0;
        MUL_op = 3'b0;
        DIV_op = 2'b0;

        if ((state == ST_READY) && issue_valid) begin
            PC_ctrl = PC;
            imm_ctrl = imm;
            rs1_ctrl = issue_src1;
            rs2_ctrl = issue_src2;

            if (use_ALU) begin
                ALU_en = 1'b1;
                ALU_use_PC = AUIPC;
                ALU_use_imm = I_valid | LUI | AUIPC;
                ALU_op = ({4{issue_alu_op == `ALU_ADD}}  & ALU_ADD)  |
                         ({4{issue_alu_op == `ALU_SUB}}  & ALU_SUB)  |
                         ({4{issue_alu_op == `ALU_AND}}  & ALU_AND)  |
                         ({4{issue_alu_op == `ALU_OR}}   & ALU_OR)   |
                         ({4{issue_alu_op == `ALU_XOR}}  & ALU_XOR)  |
                         ({4{issue_alu_op == `ALU_SLL}}  & ALU_SLL)  |
                         ({4{issue_alu_op == `ALU_SRL}}  & ALU_SRL)  |
                         ({4{issue_alu_op == `ALU_SLT}}  & ALU_SLT)  |
                         ({4{issue_alu_op == `ALU_SLTU}} & ALU_SLTU) |
                         ({4{issue_alu_op == `ALU_SRA}}  & ALU_SRA)  |
                         ({4{issue_alu_op == `ALU_LUI}}  & ALU_BOUT);
            end
            else if (use_MEM) begin
                MEM_en = 1'b1;
                MEM_we = S_valid;
                MEM_bhw = funct3;
            end
            else if (use_MUL) begin
                MUL_en = 1'b1;
            end
            else if (use_DIV) begin
                DIV_en = 1'b1;
            end
            else if (use_JUMP) begin
                JUMP_en = 1'b1;
                JUMP_op = issue_jump_op;
            end
        end
    end

    always @(*) begin
        write_sel = 3'b0;
        reg_write = 1'b0;
        rd_ctrl = 5'b0;

        if ((state == ST_WAIT) && active_done && active_reg_write) begin
            write_sel = active_write_sel;
            reg_write = 1'b1;
            rd_ctrl = active_rd;
        end
    end

endmodule
